--- a/src/runner/dependency.rs
+++ b/src/runner/dependency.rs
@@ -688,4 +688,259 @@ mod tests {

         assert!(skipped.is_empty());
     }
+
+    // --- Circular reference tests ---
+
+    #[test]
+    fn transitive_dependents_terminates_on_two_node_cycle() {
+        let graph = DependencyGraph::builder()
+            .add_step("a", vec!["b".to_string()])
+            .add_step("b", vec!["a".to_string()])
+            .build()
+            .unwrap();
+
+        let deps = graph.transitive_dependents("a");
+        assert!(deps.contains("b"));
+        // In a cycle, "a" is reachable from itself, so it appears as its own dependent
+        assert!(deps.contains("a"));
+    }
+
+    #[test]
+    fn transitive_dependents_terminates_on_three_node_cycle() {
+        let graph = DependencyGraph::builder()
+            .add_step("a", vec!["c".to_string()])
+            .add_step("b", vec!["a".to_string()])
+            .add_step("c", vec!["b".to_string()])
+            .build()
+            .unwrap();
+
+        let deps = graph.transitive_dependents("a");
+        assert!(deps.contains("b"));
+        assert!(deps.contains("c"));
+    }
+
+    #[test]
+    fn transitive_dependents_terminates_on_self_cycle() {
+        let graph = DependencyGraph::builder()
+            .add_step("a", vec!["a".to_string()])
+            .build()
+            .unwrap();
+
+        let deps = graph.transitive_dependents("a");
+        // "a" depends on itself, so "a" is its own dependent, but
+        // the start node is not included in transitive_dependents
+        assert!(deps.is_empty() || deps.contains("a"));
+    }
+
+    #[test]
+    fn transitive_dependents_cycle_with_tail() {
+        // d -> c -> b -> a -> c (cycle), d is outside the cycle
+        let graph = DependencyGraph::builder()
+            .add_step("a", vec!["c".to_string()])
+            .add_step("b", vec!["a".to_string()])
+            .add_step("c", vec!["b".to_string()])
+            .add_step("d", vec!["c".to_string()])
+            .build()
+            .unwrap();
+
+        // From "a", transitive dependents should include b, c, d
+        let deps = graph.transitive_dependents("a");
+        assert!(deps.contains("b"));
+        assert!(deps.contains("c"));
+        assert!(deps.contains("d"));
+    }
+
+    #[test]
+    fn topological_order_detects_three_node_cycle() {
+        let graph = DependencyGraph::builder()
+            .add_step("a", vec!["c".to_string()])
+            .add_step("b", vec!["a".to_string()])
+            .add_step("c", vec!["b".to_string()])
+            .build()
+            .unwrap();
+
+        let result = graph.topological_order();
+        assert!(result.is_err());
+    }
+
+    #[test]
+    fn topological_order_detects_self_cycle() {
+        let graph = DependencyGraph::builder()
+            .add_step("a", vec!["a".to_string()])
+            .build()
+            .unwrap();
+
+        let result = graph.topological_order();
+        assert!(result.is_err());
+    }
+
+    #[test]
+    fn topological_order_detects_cycle_with_acyclic_nodes() {
+        // "x" is acyclic, "a" and "b" form a cycle
+        let graph = DependencyGraph::builder()
+            .add_step("x", vec![])
+            .add_step("a", vec!["b".to_string()])
+            .add_step("b", vec!["a".to_string()])
+            .build()
+            .unwrap();
+
+        let result = graph.topological_order();
+        assert!(result.is_err());
+    }
+
+    #[test]
+    fn find_cycle_with_acyclic_subgraph() {
+        let graph = DependencyGraph::builder()
+            .add_step("x", vec![])
+            .add_step("y", vec!["x".to_string()])
+            .add_step("a", vec!["b".to_string()])
+            .add_step("b", vec!["a".to_string()])
+            .build()
+            .unwrap();
+
+        let cycle = graph.find_cycle();
+        assert!(cycle.is_some());
+        let path = cycle.unwrap();
+        // The cycle should involve a and b, not x and y
+        assert!(path.contains(&"a".to_string()) || path.contains(&"b".to_string()));
+        assert_eq!(path.first(), path.last());
+    }
+
+    #[test]
+    fn find_cycle_multiple_disjoint_cycles() {
+        let graph = DependencyGraph::builder()
+            .add_step("a", vec!["b".to_string()])
+            .add_step("b", vec!["a".to_string()])
+            .add_step("c", vec!["d".to_string()])
+            .add_step("d", vec!["c".to_string()])
+            .build()
+            .unwrap();
+
+        let cycle = graph.find_cycle();
+        assert!(cycle.is_some());
+        let path = cycle.unwrap();
+        assert_eq!(path.first(), path.last());
+    }
+
+    #[test]
+    fn parallel_groups_errors_on_cycle() {
+        let graph = DependencyGraph::builder()
+            .add_step("a", vec!["b".to_string()])
+            .add_step("b", vec!["a".to_string()])
+            .build()
+            .unwrap();
+
+        let result = graph.parallel_groups();
+        assert!(result.is_err());
+    }
+
+    #[test]
+    fn parallel_groups_errors_on_three_node_cycle() {
+        let graph = DependencyGraph::builder()
+            .add_step("a", vec!["c".to_string()])
+            .add_step("b", vec!["a".to_string()])
+            .add_step("c", vec!["b".to_string()])
+            .build()
+            .unwrap();
+
+        let result = graph.parallel_groups();
+        assert!(result.is_err());
+    }
+
+    #[test]
+    fn compute_skips_with_dependents_in_cycle() {
+        let graph = DependencyGraph::builder()
+            .add_step("a", vec!["b".to_string()])
+            .add_step("b", vec!["a".to_string()])
+            .build()
+            .unwrap();
+
+        let mut skip = HashSet::new();
+        skip.insert("a".to_string());
+
+        // Must terminate, not infinite loop
+        let skipped = graph.compute_skips(&skip, SkipBehavior::SkipWithDependents);
+        assert!(skipped.contains("a"));
+        assert!(skipped.contains("b"));
+    }
+
+    #[test]
+    fn compute_skips_skip_only_in_cycle() {
+        let graph = DependencyGraph::builder()
+            .add_step("a", vec!["b".to_string()])
+            .add_step("b", vec!["a".to_string()])
+            .build()
+            .unwrap();
+
+        let mut skip = HashSet::new();
+        skip.insert("a".to_string());
+
+        let skipped = graph.compute_skips(&skip, SkipBehavior::SkipOnly);
+        assert!(skipped.contains("a"));
+        assert!(!skipped.contains("b"));
+    }
+
+    #[test]
+    fn is_ready_in_cycle_never_ready() {
+        let graph = DependencyGraph::builder()
+            .add_step("a", vec!["b".to_string()])
+            .add_step("b", vec!["a".to_string()])
+            .build()
+            .unwrap();
+
+        // Neither node can be ready with an empty completed set
+        assert!(!graph.is_ready("a", &HashSet::new()));
+        assert!(!graph.is_ready("b", &HashSet::new()));
+    }
+
+    #[test]
+    fn circular_dependency_error_contains_cycle_nodes() {
+        let graph = DependencyGraph::builder()
+            .add_step("a", vec!["b".to_string()])
+            .add_step("b", vec!["a".to_string()])
+            .build()
+            .unwrap();
+
+        let err = graph.topological_order().unwrap_err();
+        let msg = err.to_string();
+        assert!(msg.contains("a"));
+        assert!(msg.contains("b"));
+    }
+
+    #[test]
+    fn find_cycle_empty_graph_returns_none() {
+        let graph = DependencyGraph::builder().build().unwrap();
+        assert!(graph.find_cycle().is_none());
+    }
+
+    #[test]
+    fn transitive_dependents_nonexistent_step() {
+        let graph = DependencyGraph::builder()
+            .add_step("a", vec![])
+            .build()
+            .unwrap();
+
+        let deps = graph.transitive_dependents("nonexistent");
+        assert!(deps.is_empty());
+    }
+
+    #[test]
+    fn dependencies_of_returns_none_for_unknown_step() {
+        let graph = DependencyGraph::builder()
+            .add_step("a", vec![])
+            .build()
+            .unwrap();
+
+        assert!(graph.dependencies_of("unknown").is_none());
+    }
+
+    #[test]
+    fn dependents_of_returns_none_for_unknown_step() {
+        let graph = DependencyGraph::builder()
+            .add_step("a", vec![])
+            .build()
+            .unwrap();
+
+        assert!(graph.dependents_of("unknown").is_none());
+    }
 }

